#!/usr/bin/env python3
"""Spring-quarter shipped-orders reconciliation. Working script, not a deliverable.

Subcommands:
  orders     crawl the order listing (follows "next", then a second pass by page number)
  customers  fetch each customer referenced by a qualifying order, once
  compute    dedupe, filter, discount, aggregate; write result.json
"""
import collections
import datetime as dt
import email.utils
import http.client
import json
import os
import re
import sys
import time
import urllib.parse
from fractions import Fraction

HOST, PORT = "localhost", 8080
WORK = "/tmp/recon"
RAW = os.path.join(WORK, "raw")
LOGF = os.path.join(WORK, "http.log")
RESULT = "/workspace/result.json"
MAX_WAIT = 120.0
UTC = dt.timezone.utc
RANGE_START = dt.datetime(2025, 3, 1, tzinfo=UTC)  # inclusive
RANGE_END = dt.datetime(2025, 6, 1, tzinfo=UTC)    # exclusive: through 31 May 23:59:59.999...
REGIONS = ("north", "south", "east", "west")


class Api:
    def __init__(self):
        self.token = None
        self.tokens = []
        self.counts = collections.Counter()
        self.log = open(LOGF, "a")

    def note(self, kind, **kw):
        self.counts[kind] += 1
        rec = {"t": round(time.time(), 3), "kind": kind}
        rec.update(kw)
        self.log.write(json.dumps(rec) + "\n")
        self.log.flush()

    def send(self, method, path, auth):
        headers = {"Accept": "application/json"}
        if auth:
            headers["Authorization"] = "Bearer " + self.token
        conn = http.client.HTTPConnection(HOST, PORT, timeout=30)
        try:
            conn.request(method, path, headers=headers)
            r = conn.getresponse()
            body = r.read()
            return r.status, {k.lower(): v for k, v in r.getheaders()}, body
        except (OSError, http.client.HTTPException) as e:
            return None, {}, repr(e).encode()
        finally:
            conn.close()

    def wait_hint(self, headers, body):
        """Seconds the server asked us to wait, from Retry-After and/or the JSON body."""
        waits = []
        ra = headers.get("retry-after")
        if ra is not None:
            try:
                waits.append(float(ra))
            except ValueError:
                try:
                    waits.append(email.utils.parsedate_to_datetime(ra).timestamp() - time.time())
                except (TypeError, ValueError):
                    pass
        try:
            j = json.loads(body)
        except ValueError:
            j = None
        if isinstance(j, dict):
            for key, scale in (("retry_after", 1), ("retry_after_seconds", 1), ("retry_after_ms", 0.001)):
                if isinstance(j.get(key), (int, float)) and not isinstance(j.get(key), bool):
                    waits.append(j[key] * scale)
        return waits

    def honour_rate_limit(self, path, headers, body):
        waits = self.wait_hint(headers, body)
        self.note("rate_limited", path=path, retry_after=headers.get("retry-after"),
                  body=body[:200].decode("utf-8", "replace"))
        if not waits:
            self.note("rate_limited_without_hint", path=path)
            waits = [2.0]
        if len(set(waits)) > 1:
            self.note("rate_limit_hints_disagree", path=path, waits=waits)
        wait = max(0.0, max(waits))
        if wait > MAX_WAIT:
            raise RuntimeError(f"server asked for a {wait}s wait on {path}; stopping to look")
        time.sleep(wait + 0.05)

    def fetch_token(self):
        failures = 0
        while True:
            st, hd, body = self.send("POST", "/token", False)
            snippet = body[:300].decode("utf-8", "replace")
            if st == 200:
                try:
                    tok = json.loads(body)["token"]
                    if not isinstance(tok, str) or not tok:
                        raise ValueError(tok)
                except (ValueError, KeyError, TypeError):
                    self.note("bad_token_response", body=snippet)
                    failures += 1
                else:
                    self.token = tok
                    self.tokens.append(tok)
                    self.note("token", token=tok)
                    return
            elif st == 429:
                self.honour_rate_limit("/token", hd, body)
                continue
            else:
                self.note("token_error", status=st, body=snippet, headers=hd)
                failures += 1
            if failures > 20:
                raise RuntimeError("cannot obtain a token")
            time.sleep(min(0.25 * 2 ** min(failures, 4), 4.0))

    def get(self, path, ok404=False):
        """GET a JSON document, retrying through rate limits, expired tokens and server errors.
        Returns (status, data); status is 200 or (if ok404) 404."""
        failures = 0
        auth_in_a_row = 0
        while True:
            if self.token is None:
                self.fetch_token()
            st, hd, body = self.send("GET", path, True)
            snippet = body[:300].decode("utf-8", "replace")
            if st not in (401, 403):
                auth_in_a_row = 0
            if st == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    self.note("bad_json", path=path, body=snippet)
                    failures += 1
                else:
                    self.counts["ok"] += 1
                    return 200, data
            elif st == 429:
                self.honour_rate_limit(path, hd, body)
                continue
            elif st in (401, 403):
                auth_in_a_row += 1
                self.note("auth_rejected", path=path, status=st, token=self.token, body=snippet, headers=hd)
                if auth_in_a_row > 3:
                    raise RuntimeError(f"auth keeps failing on {path}: {st} {snippet}")
                self.fetch_token()
                continue
            elif st == 404 and ok404:
                self.note("not_found", path=path, body=snippet)
                return 404, None
            else:
                self.note("error", path=path, status=st, body=snippet, headers=hd)
                failures += 1
            if failures > 25:
                raise RuntimeError(f"giving up on {path} after {failures} failures")
            time.sleep(min(0.25 * 2 ** min(failures, 4), 4.0))


def page_of(path):
    q = urllib.parse.parse_qs(urllib.parse.urlsplit(path).query)
    return int(q["page"][0])


def page_problems(data, requested):
    if not isinstance(data, dict):
        return ["not an object"]
    probs = []
    for k in ("page", "total_pages", "items", "next"):
        if k not in data:
            probs.append(f"missing {k}")
    if probs:
        return probs
    if data["page"] != requested:
        probs.append(f"page field {data['page']!r} != requested {requested}")
    if not isinstance(data["items"], list):
        probs.append("items not a list")
    elif not all(isinstance(i, dict) for i in data["items"]):
        probs.append("non-object item")
    if data["next"] is not None and not isinstance(data["next"], str):
        probs.append("next neither null nor string")
    if not isinstance(data["total_pages"], int):
        probs.append("total_pages not int")
    elif isinstance(data["items"], list):
        last = data["page"] == data["total_pages"]
        if not last and len(data["items"]) != 50:
            probs.append(f"non-final page has {len(data['items'])} items")
        if last and data["next"] is not None:
            probs.append("final page has a next link")
        if not last and data["next"] is None:
            probs.append("non-final page has no next link")
    return probs


def get_page(api, path, requested):
    for attempt in range(1, 8):
        _, data = api.get(path)
        probs = page_problems(data, requested)
        if not probs:
            return data
        api.note("bad_page", path=path, attempt=attempt, problems=probs,
                 preview=json.dumps(data)[:300])
        time.sleep(0.5)
    raise RuntimeError(f"page {path} kept failing validation: {probs}")


def save(name, obj):
    os.makedirs(RAW, exist_ok=True)
    tmp = os.path.join(RAW, name + ".tmp")
    with open(tmp, "w") as f:
        json.dump(obj, f, indent=1, sort_keys=True)
    os.replace(tmp, os.path.join(RAW, name))


def load(name):
    with open(os.path.join(RAW, name)) as f:
        return json.load(f)


def cmd_orders():
    api = Api()
    # Pass 1: follow "next" links from page 1.
    pages, sequence, total_pages = {}, [], set()
    path, visited = "/orders?page=1", set()
    while path is not None:
        if path in visited:
            raise RuntimeError(f"pagination loop at {path}")
        visited.add(path)
        n = page_of(path)
        data = get_page(api, path, n)
        if n in pages:
            raise RuntimeError(f"page {n} reached twice via next links")
        pages[n] = data
        sequence.append(n)
        total_pages.add(data["total_pages"])
        path = data["next"]
        if path is not None and page_of(path) != n + 1:
            api.note("next_not_sequential", from_page=n, next=path)
    if len(total_pages) != 1:
        raise RuntimeError(f"total_pages changed during crawl: {total_pages}")
    tp = total_pages.pop()
    missing = sorted(set(range(1, tp + 1)) - set(pages))
    for n in missing:  # should not happen, but never extrapolate
        api.note("page_missing_from_next_chain", page=n)
        pages[n] = get_page(api, f"/orders?page={n}", n)
    save("orders_pass1.json", {"sequence": sequence, "total_pages": tp,
                               "pages": {str(k): v for k, v in sorted(pages.items())}})

    # Pass 2: every page by number, to check the listing is stable between reads.
    pages2 = {n: get_page(api, f"/orders?page={n}", n) for n in range(1, tp + 1)}
    save("orders_pass2.json", {"total_pages": tp,
                               "pages": {str(k): v for k, v in sorted(pages2.items())}})
    diffs = [n for n in range(1, tp + 1) if pages[n]["items"] != pages2[n]["items"]]
    print(f"total_pages={tp} pass1 sequence ok={sequence == list(range(1, tp + 1))} "
          f"missing_from_chain={missing} pages_differing_between_passes={diffs}")
    print("tokens issued:", api.tokens)
    print("events:", dict(api.counts))


# ---------- analysis ----------

TS_SHAPE = re.compile(r"\d")


def parse_ts(s):
    """ISO 8601 -> aware UTC datetime. Raises on naive or unparseable timestamps."""
    if not isinstance(s, str):
        raise ValueError(f"placed_at not a string: {s!r}")
    d = dt.datetime.fromisoformat(s)
    if d.tzinfo is None or d.utcoffset() is None:
        raise ValueError(f"naive timestamp: {s!r}")
    return d.astimezone(UTC)


def listings(pages):
    """All order rows in listing order: (page, index, row)."""
    out = []
    for n in sorted(pages, key=int):
        for i, row in enumerate(pages[n]["items"]):
            out.append((int(n), i, row))
    return out


def dedupe(pages):
    first, dups, conflicts = {}, [], []
    for n, i, row in listings(pages):
        oid = row.get("id")
        if oid in first:
            dups.append((n, i, oid))
            if row != first[oid][2]:
                conflicts.append({"id": oid, "first": first[oid], "again": [n, i, row]})
        else:
            first[oid] = (n, i, row)
    return first, dups, conflicts


def qualifying(first):
    q, problems = [], collections.Counter()
    for oid, (_, _, row) in first.items():
        if row.get("status") != "shipped":
            continue
        try:
            when = parse_ts(row.get("placed_at"))
        except ValueError as e:
            problems[f"unparseable placed_at on shipped order: {e}"] += 1
            continue
        if RANGE_START <= when < RANGE_END:
            q.append(row)
    return q, problems


def cmd_customers():
    p1 = load("orders_pass1.json")["pages"]
    first, _, _ = dedupe(p1)
    q, _ = qualifying(first)
    ids = sorted({row["customer_id"] for row in q})
    cache_path = os.path.join(RAW, "customers.json")
    cache = load("customers.json") if os.path.exists(cache_path) else {}
    api = Api()
    for cid in ids:
        if cid in cache:
            continue
        path = "/customers/" + urllib.parse.quote(str(cid), safe="")
        st, data = api.get(path, ok404=True)
        if st == 404:
            # A 404 means unknown id; repeat it a couple of times before believing it.
            for _ in range(2):
                time.sleep(0.5)
                st, data = api.get(path, ok404=True)
                if st == 200:
                    break
        if st == 200 and (not isinstance(data, dict) or data.get("id") != cid):
            api.note("customer_id_mismatch", requested=cid, got=data)
            raise RuntimeError(f"customer {cid} returned a different record: {data}")
        cache[cid] = {"status": st, "record": data}
        save("customers.json", cache)
    print(f"customers needed={len(ids)} cached={len(cache)} "
          f"not_found={[c for c in ids if cache[c]['status'] == 404]}")
    print("tokens issued:", api.tokens)
    print("events:", dict(api.counts))


def discounted_cents(amount, pct):
    """amount * (100 - pct) / 100, rounded half up to a whole cent, exactly."""
    x = Fraction(amount) * (100 - Fraction(pct)) / 100
    return (x + Fraction(1, 2)).__floor__()


def cmd_compute():
    p1 = load("orders_pass1.json")["pages"]
    customers = load("customers.json")
    first, dups, conflicts = dedupe(p1)
    q, ts_problems = qualifying(first)

    by_region = {r: 0 for r in REGIONS}
    count_by_region = collections.Counter()
    unresolved = []
    for row in q:
        cid, amount = row["customer_id"], row["amount_cents"]
        if not isinstance(amount, int) or isinstance(amount, bool):
            unresolved.append(("amount not int", row))
            continue
        c = customers.get(cid)
        if c is None or c["status"] != 200:
            unresolved.append(("customer missing", row))
            continue
        rec = c["record"]
        pct, region = rec.get("discount_pct"), rec.get("region")
        if not isinstance(pct, int) or isinstance(pct, bool) or not 0 <= pct <= 100:
            unresolved.append((f"bad discount_pct {pct!r}", row))
            continue
        if region not in by_region:
            unresolved.append((f"bad region {region!r}", row))
            continue
        by_region[region] += discounted_cents(amount, pct)
        count_by_region[region] += 1

    result = {
        "total_cents": sum(by_region.values()),
        "order_count": len(q),
        "duplicates_skipped": len(dups),
        "by_region": by_region,
    }
    print(json.dumps(result, indent=2))
    print("count_by_region:", dict(count_by_region))
    print("unresolved:", len(unresolved))
    for why, row in unresolved[:20]:
        print("  ", why, row)
    print("timestamp problems on shipped orders:", dict(ts_problems))
    print("duplicate listings whose content differs:", len(conflicts))
    for c in conflicts[:10]:
        print("  ", c)
    if "--write" in sys.argv:
        if unresolved or ts_problems:
            raise SystemExit("refusing to write: unresolved rows")
        with open(RESULT, "w") as f:
            json.dump(result, f, indent=2)
            f.write("\n")
        print("wrote", RESULT)


if __name__ == "__main__":
    {"orders": cmd_orders, "customers": cmd_customers, "compute": cmd_compute}[sys.argv[1]]()

